#include <vector>
#include <list>
#include <chrono>

// Demonstrating complexity difference for middle insertion
void complexity_check(size_t N) {
    std::vector<int> v(N);
    std::list<int> l(N);

    // Vector: O(N) due to shifting N/2 elements
    auto it_v = v.begin();
    v.insert(it_v + N/2, 99);

    // List: O(1) given a valid iterator
    auto it_l = l.begin();
    std::advance(it_l, N/2);
    l.insert(it_l, 99);
}
